import urllib.request
import zipfile
import os
import urllib.error

def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    temp_save_path = f"{save_path}.tmp"
    download_committed = False

    def _remove_file(path: str) -> None:
        try:
            if os.path.exists(path) and not os.path.isdir(path):
                os.remove(path)
        except OSError:
            pass

    def _cleanup() -> None:
        _remove_file(temp_save_path)
        if download_committed:
            _remove_file(save_path)

    try:
        os.makedirs(os.path.dirname(temp_save_path) or ".", exist_ok=True)

        try:
            with urllib.request.urlopen(url) as response, open(temp_save_path, "wb") as out_file:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
        except urllib.error.URLError as exc:
            _cleanup()
            reason = getattr(exc, "reason", None)
            if reason is None:
                reason = str(exc)
            return f"URL Error: {reason}"
        except ValueError as exc:
            _cleanup()
            return f"URL Error: {exc}"
        except OSError as exc:
            _cleanup()
            return f"File I/O Error: {exc}"

        os.replace(temp_save_path, save_path)
        download_committed = True

        os.makedirs(extract_path, exist_ok=True)
        destination_root = os.path.abspath(extract_path)

        with zipfile.ZipFile(save_path, "r") as zip_ref:
            for member in zip_ref.infolist():
                member_path = os.path.abspath(os.path.join(destination_root, member.filename))
                if os.path.commonpath([destination_root, member_path]) != destination_root:
                    raise ValueError(f"Unsafe path in ZIP archive: {member.filename}")

            for member in zip_ref.infolist():
                zip_ref.extract(member, extract_path)

        _cleanup()
        return extract_path

    except zipfile.BadZipFile as exc:
        _cleanup()
        return f"ZIP Error: {exc}"
    except OSError as exc:
        _cleanup()
        return f"File I/O Error: {exc}"
    except ValueError as exc:
        _cleanup()
        return f"Extraction Error: {exc}"
    except Exception as exc:
        _cleanup()
        return f"Unexpected Error: {exc}"

