def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    """
    Download a ZIP file from a URL, extract it, and delete the downloaded archive.

    Returns:
        str: Path to the directory where contents were extracted, or an error message.
    """
    downloaded = False

    try:
        if not isinstance(url, str) or not url.strip():
            return "URL Error: Invalid URL"

        # Ensure output directories exist
        save_dir = os.path.dirname(os.path.abspath(save_path))
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)
        os.makedirs(extract_path, exist_ok=True)

        # Download the file in chunks
        try:
            with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
                downloaded = True
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
        except urllib.error.URLError as e:
            reason = getattr(e, "reason", e)
            return f"URL Error: {reason}"
        except ValueError as e:
            # Some malformed URLs can surface as ValueError rather than URLError.
            return f"URL Error: {e}"

        # Extract ZIP contents
        try:
            with zipfile.ZipFile(save_path, "r") as zip_ref:
                zip_ref.extractall(extract_path)
        except zipfile.BadZipFile as e:
            return f"ZIP Error: {e}"
        except (OSError, IOError) as e:
            return f"File Error: {e}"

        return os.path.abspath(extract_path)

    except (OSError, IOError) as e:
        return f"File Error: {e}"
    except Exception as e:
        return f"Unexpected Error: {e}"
    finally:
        # Delete the ZIP file if it was downloaded or partially created.
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except OSError:
            pass

