import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

def task_func(s1, s2):
    def _as_series(obj):
        if isinstance(obj, pd.Series):
            return obj.reset_index(drop=True)
        if isinstance(obj, (str, bytes)):
            return pd.Series([obj])
        try:
            return pd.Series(list(obj))
        except TypeError:
            return pd.Series([obj])

    s1 = _as_series(s1).dropna().reset_index(drop=True)
    s2 = _as_series(s2).dropna().reset_index(drop=True)

    common_values = pd.Index(pd.unique(s1)).intersection(pd.Index(pd.unique(s2)), sort=False)
    intersection_count = int(len(common_values))

    data = pd.DataFrame(
        {
            "series": ["s1"] * len(s1) + ["s2"] * len(s2),
            "value": pd.concat([s1, s2], ignore_index=True),
        }
    )

    fig, ax = plt.subplots()
    sns.swarmplot(data=data, x="series", y="value", ax=ax)

    if intersection_count > 0:
        ax.hlines(
            y=common_values.tolist(),
            xmin=0,
            xmax=1,
            colors="red",
            linestyles="--",
            linewidth=1.5,
            zorder=0,
        )

    ax.set_xlabel("")
    ax.set_ylabel("Value")
    ax.set_title("Swarm plot of two series with intersections highlighted")

    return ax, intersection_count

import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    """
    Download a ZIP file from `url`, extract it into `extract_path`,
    delete the downloaded ZIP, and return `extract_path` on success.

    On failure, returns a descriptive error string.
    """

    def _cleanup_download() -> None:
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except OSError:
            pass

    def _safe_target_path(member_name: str) -> str:
        base_dir = os.path.abspath(extract_path)
        target_path = os.path.abspath(os.path.join(base_dir, member_name))
        if target_path == base_dir or target_path.startswith(base_dir + os.sep):
            return target_path
        raise OSError(f"Unsafe path detected in ZIP archive: {member_name}")

    try:
        os.makedirs(extract_path, exist_ok=True)
        save_dir = os.path.dirname(save_path)
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)
    except OSError as e:
        return f"File I/O Error: {e}"

    try:
        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)
    except (urllib.error.URLError, ValueError) as e:
        _cleanup_download()
        reason = getattr(e, "reason", e)
        return f"URL Error: {reason}"
    except OSError as e:
        _cleanup_download()
        return f"File I/O Error: {e}"

    try:
        with zipfile.ZipFile(save_path, "r") as zip_obj:
            for member in zip_obj.infolist():
                target_path = _safe_target_path(member.filename)

                if member.is_dir():
                    os.makedirs(target_path, exist_ok=True)
                    continue

                parent_dir = os.path.dirname(target_path)
                if parent_dir:
                    os.makedirs(parent_dir, exist_ok=True)

                with zip_obj.open(member, "r") as source, open(target_path, "wb") as target:
                    while True:
                        data = source.read(8192)
                        if not data:
                            break
                        target.write(data)
    except zipfile.BadZipFile:
        _cleanup_download()
        return "ZIP Error: corrupted or invalid ZIP file"
    except OSError as e:
        _cleanup_download()
        return f"File I/O Error: {e}"
    except Exception as e:
        _cleanup_download()
        return f"Unexpected Error: {e}"

    try:
        os.remove(save_path)
    except OSError as e:
        return f"File I/O Error: {e}"

    return extract_path

