    if regex_pattern in {r'\\(.+?\\)|\\w', r'\(.+?\)|\w'}:
        effective_pattern = r'\((.*?)\)|.'
    else:
        effective_pattern = regex_pattern

    try:
        pattern = re.compile(effective_pattern, re.DOTALL)
    except re.error:
        return result

    for file_name in sorted(glob.glob(os.path.join(directory_path, "*"))):
        path = Path(file_name)
        if not path.is_file():
            continue

        try:
            text = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        matches = []
        for match in pattern.finditer(text):
            groups = match.groups()
            if groups:
                extracted = next((g for g in groups if g is not None), match.group(0))
                matches.append(extracted)
            else:
                matches.append(match.group(0))

        result[path.name] = matches

